function askConfirm(title,message,confirmText='确定',danger=false){return new Promise(resolve=>{const previousFocus=document.activeElement,dialogId='confirm-'+crypto.randomUUID(),descriptionId=dialogId+'-description';const overlay=document.createElement('div');overlay.className='dialog-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby',dialogId);overlay.setAttribute('aria-describedby',descriptionId);const dialog=document.createElement('section');dialog.className='confirm-dialog';const heading=document.createElement('h3');heading.id=dialogId;heading.textContent=title;const copy=document.createElement('p');copy.id=descriptionId;copy.textContent=message;const actions=document.createElement('div');actions.className='dialog-actions';const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='取消';const confirm=document.createElement('button');confirm.type='button';confirm.className=danger?'confirm-danger':'';confirm.textContent=confirmText;actions.append(cancel,confirm);dialog.append(heading,copy,actions);overlay.append(dialog);document.body.append(overlay);document.body.classList.add('modal-open');let keyHandler,finished=false;const finish=value=>{if(finished)return;finished=true;if(keyHandler)document.removeEventListener('keydown',keyHandler);overlay.classList.add('closing');window.setTimeout(()=>{overlay.remove();if(!document.querySelector('.dialog-overlay'))document.body.classList.remove('modal-open');if(previousFocus instanceof HTMLElement&&document.contains(previousFocus))previousFocus.focus();},160);resolve(value);};cancel.addEventListener('click',()=>finish(false));confirm.addEventListener('click',()=>finish(true));overlay.addEventListener('click',event=>{if(event.target===overlay)finish(false);});keyHandler=event=>{if(event.key==='Escape'){event.preventDefault();finish(false);return;}if(event.key==='Tab'){const first=cancel,last=confirm;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}};document.addEventListener('keydown',keyHandler);confirm.focus();});}
