function setPreferredSnapshot(snapshot){preferredState.available=Boolean(snapshot?.available);preferredState.checkedAt=snapshot?.checkedAt||'';preferredState.expiresAt=snapshot?.expiresAt||'';preferredState.collected=snapshot?.collected||null;const panel=$('#sourceResult');if(preferredState.collected){renderSourceResult(preferredState.collected);$('#output').textContent=JSON.stringify(preferredState.collected,null,2);}else panel?.classList.add('hidden');updatePreferredSummary();}
