if(telegramSettingsCard){const token=$('#telegramBotToken'),secret=$('#telegramWebhookSecret'),users=$('#telegramAllowedUserIds');if(token&&secret&&users){const credentials=document.createElement('div');credentials.className='telegram-credentials';const tokenField=document.createElement('div');tokenField.append(token.previousElementSibling,token);const secretField=document.createElement('div');secretField.append(secret.previousElementSibling,secret);const userField=document.createElement('div');userField.className='telegram-user-field';userField.append(users.previousElementSibling,users);credentials.append(tokenField,secretField,userField);telegramSettingsCard.insertBefore(credentials,$('#telegramConfigStatus'));}const actions=$('#saveTelegram')?.closest('.actions');if(actions){actions.classList.add('telegram-actions');$('#saveTelegram')?.classList.add('primary-action');}}
const updateThemeAccessibility=()=>{const themeButton=$('#theme');if(!themeButton)return;const light=document.body.classList.contains('light');themeButton.dataset.icon=light?'☾':'☼';themeButton.setAttribute('aria-label',light?'切换到深色主题':'切换到浅色主题');themeButton.setAttribute('aria-pressed',String(light));};const themeObserver=new MutationObserver(updateThemeAccessibility);themeObserver.observe(document.body,{attributes:true,attributeFilter:['class']});updateThemeAccessibility();
const updateNavigationAccessibility=()=>{document.querySelectorAll('.nav button,#mobileMenu button').forEach(button=>{if(button.classList.contains('active'))button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});const toggle=$('#mobileMenuToggle');if(toggle)toggle.setAttribute('aria-label',toggle.getAttribute('aria-expanded')==='true'?'关闭页面导航':'打开页面导航');};const navigationObserver=new MutationObserver(updateNavigationAccessibility);document.querySelectorAll('.nav,#mobileMenu').forEach(nav=>navigationObserver.observe(nav,{subtree:true,attributes:true,attributeFilter:['class']}));document.querySelector('#mobileMenuToggle')?.addEventListener('click',()=>queueMicrotask(updateNavigationAccessibility));updateNavigationAccessibility();
